### 3. src/auth.ts
Authentication routes for registration and login. Uses Bun's password hashing. Implements Bearer token-based auth middleware for protected routes.

**Path:** `C:\Users\chuan\AppData\Local\Temp\mirrorcode-overlay-benchmark-project-DWmpS6\src\auth.ts`

```typescript
import { Hono } from 'hono';
import { db } from './db.js';
import type { User, Session } from './types.js';
import type { Context, Next } from 'hono';

type AuthEnv = {
  Variables: {
    user: User;
  };
};

export const authRoutes = new Hono();

authRoutes.post('/register', async (c) => {
  const body = await c.req.json<{ username: string; password: string }>();
  const { username, password } = body;

  if (!username || !password) {
    return c.json({ error: '用户名和密码不能为空' }, 400);
  }

  if (username.length < 2 || password.length < 4) {
    return c.json({ error: '用户名至少2位，密码至少4位' }, 400);
  }

  const existing = db.query('SELECT id FROM users WHERE username = ?').get(username);
  if (existing) {
    return c.json({ error: '用户名已存在' }, 400);
  }

  const passwordHash = await Bun.password.hash(password);
  const result = db.query(
    'INSERT INTO users (username, password_hash, balance) VALUES (?, ?, 1000000) RETURNING id, username, balance'
  ).get(username, passwordHash) as { id: number; username: string; balance: number };

  return c.json({ id: result.id, username: result.username, balance: result.balance }, 201);
});

authRoutes.post('/login', async (c) => {
  const body = await c.req.json<{ username: string; password: string }>();
  const { username, password } = body;

  if (!username || !password) {
    return c.json({ error: '用户名和密码不能为空' }, 400);
  }

  const user = db.query('SELECT * FROM users WHERE username = ?').get(username) as User | null;
  if (!user) {
    return c.json({ error: '用户名或密码错误' }, 401);
  }

  const valid = await Bun.password.verify(password, user.password_hash);
  if (!valid) {
    return c.json({ error: '用户名或密码错误' }, 401);
  }

  const token = crypto.randomUUID();
  db.query('INSERT INTO sessions (token, user_id) VALUES (?, ?)').run(token, user.id);

  return c.json({ token, username: user.username, balance: user.balance });
});

export function authMiddleware() {
  return async (c: Context<AuthEnv>, next: Next) => {
    const authHeader = c.req.header('Authorization');
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return c.json({ error: '未授权' }, 401);
    }

    const token = authHeader.slice(7);
    const session = db.query('SELECT * FROM sessions WHERE token = ?').get(token) as Session | null;
    if (!session) {
      return c.json({ error: '无效的令牌' }, 401);
    }

    const user = db.query('SELECT * FROM users WHERE id = ?').get(session.user_id) as User | null;
    if (!user) {
      return c.json({ error: '用户不存在' }, 401);
    }

    c.set('user', user);
    await next();
  };
}
```

### 4. src/market.ts
Market data endpoints. Provides GET endpoints for stock list, individual stock details with price history, and Server-Sent Events (SSE) for real-time price updates.

**Path:** `C:\Users\chuan\AppData\Local\Temp\mirrorcode-overlay-benchmark-project-DWmpS6\src\market.ts`

```typescript
import { Hono } from 'hono';
import { streamSSE } from 'hono/streaming';
import { db } from './db.js';
import { addSSESubscriber, removeSSESubscriber } from './simulator.js';
import type { Stock, PriceHistory } from './types.js';

export const marketRoutes = new Hono();

marketRoutes.get('/stocks', (c) => {
  const stocks = db.query('SELECT * FROM stocks').all() as Stock[];
  const result = stocks.map(s => ({
    code: s.code,
    name: s.name,
    current_price: s.current_price,
    open_price: s.open_price,
    high_price: s.high_price,
    low_price: s.low_price,
    change: Math.round((s.current_price - s.open_price) * 100) / 100,
    change_percent: Math.round(((s.current_price - s.open_price) / s.open_price) * 1000) / 10,
    volume: s.volume,
  }));
  return c.json(result);
});

marketRoutes.get('/stocks/:code', (c) => {
  const code = c.req.param('code');
  const stock = db.query('SELECT * FROM stocks WHERE code = ?').get(code) as Stock | null;

  if (!stock) {
    return c.json({ error: '股票不存在' }, 404);
  }

  const history = db.query(
    'SELECT * FROM price_history WHERE stock_code = ? ORDER BY created_at DESC LIMIT 60'
  ).all(code) as PriceHistory[];

  return c.json({
    code: stock.code,
    name: stock.name,
    current_price: stock.current_price,
    open_price: stock.open_price,
    high_price: stock.high_price,
    low_price: stock.low_price,
    change: Math.round((stock.current_price - stock.open_price) * 100) / 100,
    change_percent: Math.round(((stock.current_price - stock.open_price) / stock.open_price) * 1000) / 10,
    volume: stock.volume,
    history: history.reverse().map(h => ({
      price: h.price,
      volume: h.volume,
      time: h.created_at,
    })),
  });
});

marketRoutes.get('/sse', (c) => {
  return streamSSE(c, async (stream) => {
    let closed = false;

    const handler = (data: string) => {
      if (!closed) {
        stream.writeSSE({ data, event: 'prices' }).catch(() => {
          closed = true;
        });
      }
    };

    addSSESubscriber(handler);

    const stocks = db.query('SELECT * FROM stocks').all() as Stock[];
    const initialData = JSON.stringify(stocks.map(s => ({
      code: s.code,
      name: s.name,
      current_price: s.current_price,
      open_price: s.open_price,
      high_price: s.high_price,
      low_price: s.low_price,
      change: Math.round((s.current_price - s.open_price) * 100) / 100,
      change_percent: Math.round(((s.current_price - s.open_price) / s.open_price) * 1000) / 10,
      volume: s.volume,
    })));
    await stream.writeSSE({ data: initialData, event: 'prices' });

    while (!closed) {
      await stream.sleep(1000);
    }

    removeSSESubscriber(handler);
  });
});
```

