97	export class SSEManager {
98	  private eventSource: EventSource | null = null;
99	  private onMessage: ((stocks: StockData[]) => void) | null = null;
100	  private onStatusChange: ((connected: boolean) => void) | null = null;
101	  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
102	
103	  connect(onMessage: (stocks: StockData[]) => void, onStatusChange?: (connected: boolean) => void): void {
104	    this.onMessage = onMessage;
105	    this.onStatusChange = onStatusChange || null;
106	    this.doConnect();
107	  }
108	
109	  private doConnect(): void {
110	    if (this.eventSource) {
111	      this.eventSource.close();
112	    }
113	
114	    this.eventSource = new EventSource(`${API_BASE}/market/sse`);
115	
116	    this.eventSource.addEventListener('prices', (event: MessageEvent) => {
117	      try {
118	        const stocks = JSON.parse(event.data) as StockData[];
119	        this.onMessage?.(stocks);
120	      } catch {
121	        // ignore parse errors
122	      }
123	    });
124	
125	    this.eventSource.onopen = () => {
126	      this.onStatusChange?.(true);
127	    };
128	
129	    this.eventSource.onerror = () => {
130	      this.onStatusChange?.(false);
131	      this.eventSource?.close();
132	      this.reconnectTimer = setTimeout(() => this.doConnect(), 3000);
133	    };
134	  }
135	
136	  disconnect(): void {
137	    if (this.reconnectTimer) {
138	      clearTimeout(this.reconnectTimer);
139	      this.reconnectTimer = null;
140	    }
141	    if (this.eventSource) {
142	      this.eventSource.close();
143	      this.eventSource = null;
144	    }
145	    this.onStatusChange?.(false);
146	  }
147	}
