11	export function generateNextPrice(currentPrice: number, openPrice: number, trend: number): number {
12	  const sigma = 0.005;
13	  const randomChange = randomNormal() * sigma;
14	  const newPrice = currentPrice * (1 + randomChange + trend);
15	  const upperLimit = openPrice * 1.1;
16	  const lowerLimit = openPrice * 0.9;
17	  const clampedPrice = Math.max(lowerLimit, Math.min(upperLimit, newPrice));
18	  return Math.round(clampedPrice * 100) / 100;
19	}
