### 3. src/auth.ts
Authentication routes for registration and login. Uses Bun's password hashing. Implements Bearer token-based auth middleware for protected routes.

**Path:** `C:\Users\chuan\AppData\Local\Temp\mirrorcode-overlay-benchmark-project-DWmpS6\src\auth.ts`

```typescript
import { Hono } from 'hono';
import { db } from './db.js';
import type { User, Session } from './types.js';
import type { Context, Next } from 'hono';

type AuthEnv = {
  Variables: {
    user: User;
  };
};

export const authRoutes = new Hono();

authRoutes.post('/register', async (c) => {
  const body = await c.req.json<{ username: string; password: string }>();
  const { username, password } = body;

  if (!username || !password) {
    return c.json({ error: '用户名和密码不能为空' }, 400);
  }

  if (username.length < 2 || password.length < 4) {
    return c.json({ error: '用户名至少2位，密码至少4位' }, 400);
  }

  const existing = db.query('SELECT id FROM users WHERE username = ?').get(username);
  if (existing) {
    return c.json({ error: '用户名已存在' }, 400);
  }

  const passwordHash = await Bun.password.hash(password);
  const result = db.query(
    'INSERT INTO users (username, password_hash, balance) VALUES (?, ?, 1000000) RETURNING id, username, balance'
  ).get(username, passwordHash) as { id: number; username: string; balance: number };

  return c.json({ id: result.id, username: result.username, balance: result.balance }, 201);
});

authRoutes.post('/login', async (c) => {
  const body = await c.req.json<{ username: string; password: string }>();
  const { username, password } = body;

  if (!username || !password) {
    return c.json({ error: '用户名和密码不能为空' }, 400);
  }

  const user = db.query('SELECT * FROM users WHERE username = ?').get(username) as User | null;
  if (!user) {
    return c.json({ error: '用户名或密码错误' }, 401);
  }

  const valid = await Bun.password.verify(password, user.password_hash);
  if (!valid) {
    return c.json({ error: '用户名或密码错误' }, 401);
  }

  const token = crypto.randomUUID();
  db.query('INSERT INTO sessions (token, user_id) VALUES (?, ?)').run(token, user.id);

  return c.json({ token, username: user.username, balance: user.balance });
});

export function authMiddleware() {
  return async (c: Context<AuthEnv>, next: Next) => {
    const authHeader = c.req.header('Authorization');
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return c.json({ error: '未授权' }, 401);
    }

    const token = authHeader.slice(7);
    const session = db.query('SELECT * FROM sessions WHERE token = ?').get(token) as Session | null;
    if (!session) {
      return c.json({ error: '无效的令牌' }, 401);
    }

    const user = db.query('SELECT * FROM users WHERE id = ?').get(session.user_id) as User | null;
    if (!user) {
      return c.json({ error: '用户不存在' }, 401);
    }

    c.set('user', user);
    await next();
  };
}
```

