```typescript
import { Hono } from 'hono';
import { streamSSE } from 'hono/streaming';
import { db } from './db.js';
import { addSSESubscriber, removeSSESubscriber } from './simulator.js';
import type { Stock, PriceHistory } from './types.js';

export const marketRoutes = new Hono();

marketRoutes.get('/stocks', (c) => {
  const stocks = db.query('SELECT * FROM stocks').all() as Stock[];
  const result = stocks.map(s => ({
    code: s.code,
    name: s.name,
    current_price: s.current_price,
    open_price: s.open_price,
    high_price: s.high_price,
    low_price: s.low_price,
    change: Math.round((s.current_price - s.open_price) * 100) / 100,
    change_percent: Math.round(((s.current_price - s.open_price) / s.open_price) * 1000) / 10,
    volume: s.volume,
  }));
  return c.json(result);
});

marketRoutes.get('/stocks/:code', (c) => {
  const code = c.req.param('code');
  const stock = db.query('SELECT * FROM stocks WHERE code = ?').get(code) as Stock | null;

  if (!stock) {
    return c.json({ error: '股票不存在' }, 404);
  }

  const history = db.query(
    'SELECT * FROM price_history WHERE stock_code = ? ORDER BY created_at DESC LIMIT 60'
  ).all(code) as PriceHistory[];

  return c.json({
    code: stock.code,
    name: stock.name,
    current_price: stock.current_price,
    open_price: stock.open_price,
    high_price: stock.high_price,
    low_price: stock.low_price,
    change: Math.round((stock.current_price - stock.open_price) * 100) / 100,
    change_percent: Math.round(((stock.current_price - stock.open_price) / stock.open_price) * 1000) / 10,
    volume: stock.volume,
    history: history.reverse().map(h => ({
      price: h.price,
      volume: h.volume,
      time: h.created_at,
    })),
  });
});

marketRoutes.get('/sse', (c) => {
  return streamSSE(c, async (stream) => {
    let closed = false;

    const handler = (data: string) => {
      if (!closed) {
        stream.writeSSE({ data, event: 'prices' }).catch(() => {
          closed = true;
        });
      }
    };

    addSSESubscriber(handler);

    const stocks = db.query('SELECT * FROM stocks').all() as Stock[];
    const initialData = JSON.stringify(stocks.map(s => ({
      code: s.code,
      name: s.name,
      current_price: s.current_price,
      open_price: s.open_price,
      high_price: s.high_price,
      low_price: s.low_price,
      change: Math.round((s.current_price - s.open_price) * 100) / 100,
      change_percent: Math.round(((s.current_price - s.open_price) / s.open_price) * 1000) / 10,
      volume: s.volume,
    })));
    await stream.writeSSE({ data: initialData, event: 'prices' });

    while (!closed) {
      await stream.sleep(1000);
    }

    removeSSESubscriber(handler);
  });
});
```

