4	function randomNormal(): number {
5	  let u = 0, v = 0;
6	  while (u === 0) u = Math.random();
7	  while (v === 0) v = Math.random();
8	  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
9	}
