21	export function generateInitialHistory(): void {
22	  const stocks = db.query('SELECT * FROM stocks').all() as Stock[];
23	  const now = Math.floor(Date.now() / 1000);
24	
25	  const insertHistory = db.prepare(
26	    'INSERT INTO price_history (stock_code, price, volume, created_at) VALUES (?, ?, ?, ?)'
27	  );
28	  const updateStock = db.prepare(
29	    'UPDATE stocks SET current_price = ?, high_price = ?, low_price = ?, volume = ?, updated_at = ? WHERE code = ?'
30	  );
31	
32	  const transaction = db.transaction(() => {
33	    for (const stock of stocks) {
34	      let price = stock.open_price;
35	      let high = price;
36	      let low = price;
37	      let totalVolume = 0;
38	
39	      for (let i = 0; i < 60; i++) {
40	        price = generateNextPrice(price, stock.open_price, stock.trend);
41	        const vol = Math.floor(Math.random() * 10000) + 1000;
42	        totalVolume += vol;
43	        high = Math.max(high, price);
44	        low = Math.min(low, price);
45	        const timestamp = now - (60 - i) * 2;
46	        insertHistory.run(stock.code, price, vol, timestamp);
47	      }
48	
49	      updateStock.run(price, high, low, totalVolume, now, stock.code);
50	    }
51	  });
52	
53	  transaction();
