85	function matchOrders(): void {
86	  const stocks = db.query('SELECT code, current_price FROM stocks').all() as Pick<Stock, 'code' | 'current_price'>[];
87	  const now = Math.floor(Date.now() / 1000);
88	
89	  const transaction = db.transaction(() => {
90	    for (const stock of stocks) {
91	      const buyOrders = db.query(
92	        "SELECT * FROM orders WHERE stock_code = ? AND direction = 'buy' AND status = 'pending' AND price >= ?"
93	      ).all(stock.code, stock.current_price) as Order[];
94	
95	      for (const order of buyOrders) {
96	        db.query("UPDATE orders SET status = 'filled', filled_at = ? WHERE id = ?").run(now, order.id);
97	
98	        const existingPos = db.query(
99	          'SELECT * FROM positions WHERE user_id = ? AND stock_code = ?'
100	        ).get(order.user_id, order.stock_code) as Position | null;
101	
102	        if (existingPos) {
103	          const totalCost = existingPos.quantity * existingPos.cost_basis + order.quantity * stock.current_price;
104	          const totalQty = existingPos.quantity + order.quantity;
105	          const newCostBasis = totalCost / totalQty;
106	          db.query('UPDATE positions SET quantity = ?, cost_basis = ? WHERE id = ?').run(totalQty, newCostBasis, existingPos.id);
107	        } else {
108	          db.query(
109	            'INSERT INTO positions (user_id, stock_code, quantity, cost_basis) VALUES (?, ?, ?, ?)'
110	          ).run(order.user_id, order.stock_code, order.quantity, stock.current_price);
111	        }
112	      }
113	
114	      const sellOrders = db.query(
115	        "SELECT * FROM orders WHERE stock_code = ? AND direction = 'sell' AND status = 'pending' AND price <= ?"
116	      ).all(stock.code, stock.current_price) as Order[];
117	
118	      for (const order of sellOrders) {
119	        db.query("UPDATE orders SET status = 'filled', filled_at = ? WHERE id = ?").run(now, order.id);
120	        const proceeds = order.quantity * stock.current_price;
121	        db.query('UPDATE users SET balance = balance + ? WHERE id = ?').run(proceeds, order.user_id);
122	
123	        const pos = db.query(
124	          'SELECT * FROM positions WHERE user_id = ? AND stock_code = ?'
125	        ).get(order.user_id, order.stock_code) as Position | null;
126	
127	        if (pos) {
128	          const newQty = pos.quantity - order.quantity;
129	          if (newQty <= 0) {
130	            db.query('DELETE FROM positions WHERE id = ?').run(pos.id);
131	          } else {
132	            db.query('UPDATE positions SET quantity = ? WHERE id = ?').run(newQty, pos.id);
133	          }
134	        }
135	      }
136	    }
137	  });
138	
139	  transaction();
140	}
