153	function broadcastPrices(): void {
154	  if (subscribers.size === 0) return;
155	  const stocks = db.query('SELECT * FROM stocks').all() as Stock[];
156	  const data = JSON.stringify(stocks.map(s => ({
157	    code: s.code,
158	    name: s.name,
159	    current_price: s.current_price,
160	    open_price: s.open_price,
161	    high_price: s.high_price,
162	    low_price: s.low_price,
163	    change: Math.round((s.current_price - s.open_price) * 100) / 100,
164	    change_percent: Math.round(((s.current_price - s.open_price) / s.open_price) * 1000) / 10,
165	    volume: s.volume,
166	  })));
167	
168	  for (const sub of subscribers) {
169	    try {
170	      sub(data);
171	    } catch {
172	      subscribers.delete(sub);
173	    }
174	  }
175	}
